var o=24;var r=`024-temperature-danger-zone-and-time-control`;var i=`012`;var a={en:`Temperature Danger Zone and Time Control`,ua:`Температурна зона небезпеки та контроль часу`};var n={short:`Many harmful bacteria can grow rapidly when perishable foods remain at intermediate temperatures. Temperature control works together with time limits; neither refrigeration nor hot holding should be treated as optional.`,sections:[{title:`Core idea`,text:`The US Department of Agriculture teaches a consumer danger zone of about 4.4–60°C (40–140°F). Some professional food codes use specific operating limits, such as 5°C (41°F) cold holding and 57°C (135°F) hot holding; they should not be confused with the broader consumer teaching range.`},{title:`Scientific / practical principles`,text:`Time matters because bacteria may multiply during exposure. The US two-hour consumer rule calls for refrigerating perishable food within two hours, or one hour when ambient conditions exceed 32°C (90°F). Bacterial growth is not guaranteed at every temperature, but risk increases with poor control.`},{title:`How to apply it`,text:`Keep refrigerated food at or below about 4°C (40°F) under US home guidance; maintain hot food at a safe hot-holding temperature and check with a thermometer. During parties or service, track how long food sits out and replenish small portions rather than leaving large trays exposed.`},{title:`Practical example`,text:`A chicken salad left on a picnic table for three hours in ordinary warm weather has exceeded the US two-hour limit and should be discarded, even if it still smells normal.`},{title:`Common mistakes and limitations`,text:`The danger zone is not a single magic temperature at which food suddenly becomes unsafe. Do not count only the latest exposure and forget previous periods; do not use smell or a brief reheating to justify unsafe storage.`}]};var s={short:`Багато небезпечних бактерій швидко ростуть, коли швидкопсувні продукти довго перебувають за проміжних температур. Контроль температури потрібно поєднувати з обмеженням часу, а охолодження й гаряче зберігання не є необов’язковими.`,sections:[{title:`Суть`,text:`Міністерство сільського господарства США використовує для побутових рекомендацій зону небезпеки приблизно 4,4–60°C (40–140°F). Професійні харчові кодекси іноді встановлюють окремі межі, наприклад 5°C (41°F) для холодного та 57°C (135°F) для гарячого зберігання. Ці системи не слід змішувати.`},{title:`Наукові та практичні принципи`,text:`Час важливий, оскільки мікроорганізми можуть розмножуватися під час перебування в небезпечних умовах. Американське побутове правило: охолоджуйте швидкопсувну їжу не пізніше ніж за дві години або за одну годину, якщо навколишня температура перевищує 32°C (90°F).`},{title:`Як застосовувати`,text:`За американськими домашніми рекомендаціями тримайте холодильник за температури близько 4°C (40°F) або нижче, а гарячі страви тримайте за безпечної температури підтримання тепла. Контролюйте час під час подачі та викладайте невеликі порції замість довгого зберігання великих підносів на столі.`},{title:`Практичний приклад`,text:`Курячий салат, який стояв на пікніку три години в теплу погоду, перевищив американську двогодинну межу і його потрібно викинути, навіть якщо запах не змінився.`},{title:`Поширені помилки й обмеження`,text:`Зона небезпеки не є чарівною межею, після перетину якої продукт миттєво стає зіпсованим. Враховуйте всі періоди неправильного зберігання й не намагайтеся виправдати їх запахом чи коротким повторним підігріванням.`}]};var l=[20,23,25,26];var h=`References / Джерела`;var d=[`https://www.who.int/publications/i/item/9789241594639`,`https://ask.fsis.usda.gov/article/What-is-the-Danger-Zone`,`https://www.fda.gov/food/buy-store-serve-safe-food/safe-food-handling`,`https://www.who.int/activities/promoting-safe-food-handling/five-key-to-safer-food/`];var c={id:24,slug:r,group:`012`,title:a,en:n,ua:s,related:l,referenceTitle:h,references:d};export{c as default,n as en,i as group,o as id,h as referenceTitle,d as references,l as related,r as slug,a as title,s as ua};